 const input=document.getElementById('spUfInput');const check=()=>{const value=String(input?.value||'').trim();if(!value)return;if(S().equal(value,item.answer))S().right(themeNo(),task.id,task.items.length,idx,value);else S().wrong(themeNo(),task.id,task.items.length,idx,value);contextScramble(task)};
